'use client';

import React from 'react';

/** A single tab definition. */
export interface TabItem {
  /** Unique value identifying this tab. */
  value: string;
  /** Label displayed on the tab trigger. */
  label: string;
  /** Content rendered when this tab is active. */
  content?: React.ReactNode;
}

/** Props for the {@link Tabs} component. */
export interface TabsProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Array of tab definitions. */
  tabs: TabItem[];
  /** The currently active tab value (controlled). */
  value?: string;
  /** Default active tab value (uncontrolled). */
  defaultValue?: string;
  /** Called when the active tab changes. */
  onValueChange?: (value: string) => void;
  /** Additional CSS class names. */
  className?: string;
}

/**
 * Tabbed navigation with dither tab indicator.
 * Manages active tab state internally or via controlled `value` prop.
 */
export const Tabs = React.forwardRef<HTMLDivElement, TabsProps>(
  ({ tabs, value, defaultValue, onValueChange, className, ...rest }, ref) => {
    const [internal, setInternal] = React.useState(defaultValue ?? tabs[0]?.value ?? '');
    const active = value ?? internal;

    const select = React.useCallback(
      (v: string) => {
        if (value === undefined) setInternal(v);
        onValueChange?.(v);
      },
      [value, onValueChange],
    );

    return (
      <div ref={ref} className={`sk-tabs${className ? ` ${className}` : ''}`} {...rest}>
        <div className="sk-tabs__list" role="tablist">
          {tabs.map((t) => (
            <button
              key={t.value}
              className="sk-tabs__trigger"
              role="tab"
              aria-selected={active === t.value}
              onClick={() => select(t.value)}
            >
              {t.label}
            </button>
          ))}
        </div>
        {tabs.map((t) => (
          <div
            key={t.value}
            className="sk-tabs__content"
            role="tabpanel"
            hidden={active !== t.value}
          >
            {t.content}
          </div>
        ))}
      </div>
    );
  },
);

Tabs.displayName = 'Tabs';

/**
 * skeehn — Tabs Component
 *
 * @component sk-tabs
 * @variants  default | [data-variant="pixel"] | [data-variant="retro"] | [data-variant="ascii"]
 * @states    [aria-selected] | [data-loading] | [data-skeleton]
 * @slots     __list | __trigger | __content | __panel-title
 * @a11y      aria-selected, keyboard navigation, focus-visible ring
 * @print     Active tab content visible, tab list as text
 */

.sk-tabs { width: 100%; font-family: var(--sk-font-mono); }
.sk-tabs__list { display: inline-flex; gap: var(--sk-space-1); padding: var(--sk-space-1); background: hsl(var(--sk-muted)); border-radius: var(--sk-radius); position: relative; }
.sk-tabs__trigger { padding: var(--sk-space-2) var(--sk-space-3); font-family: var(--sk-font-mono); font-size: var(--sk-font-size-xs); font-weight: 500; letter-spacing: 0.02em; text-transform: uppercase; color: hsl(var(--sk-muted-foreground)); background: transparent; border: none; border-radius: var(--sk-radius); cursor: pointer; transition: all var(--sk-transition-fast); position: relative; }
.sk-tabs__trigger:hover { color: hsl(var(--sk-foreground)); }
.sk-tabs__trigger[aria-selected="true"] { color: hsl(var(--sk-foreground)); background: hsl(var(--sk-background)); }
.sk-tabs__trigger[aria-selected="true"]::before { content: ""; position: absolute; inset: 0; background-image: var(--sk-dither-pattern); background-repeat: repeat; opacity: calc(var(--sk-dither-opacity, 0.15) * 0.3); pointer-events: none; border-radius: inherit; }
.sk-tabs__content { margin-top: var(--sk-space-3); padding: var(--sk-space-3); border: var(--sk-border); border-radius: var(--sk-radius); }
.sk-tabs__content[hidden] { display: none; }
.sk-tabs__panel-title { margin: 0 0 var(--sk-space-2); font-size: var(--sk-font-size-sm); font-weight: 600; letter-spacing: 0.02em; }
.sk-tabs__content p { margin: 0; color: hsl(var(--sk-muted-foreground)); font-size: var(--sk-font-size-sm); }

/* Micro-interactions */
.sk-tabs__trigger:hover { color: hsl(var(--sk-foreground)); transform: translateY(-1px); }
.sk-tabs__trigger:active { transform: translateY(1px); }
.sk-tabs__trigger:focus-visible { outline: 2px solid hsl(var(--sk-ring)); outline-offset: 2px; }

/* Pixel variant */
.sk-tabs[data-variant="pixel"] .sk-tabs__list { background: hsl(var(--sk-background)); border: 2px solid hsl(var(--sk-foreground)); box-shadow: 3px 3px 0 hsl(var(--sk-foreground)); }
.sk-tabs[data-variant="pixel"] .sk-tabs__content { border: 2px solid hsl(var(--sk-foreground)); box-shadow: 3px 3px 0 hsl(var(--sk-foreground)); }

/* Retro variant */
.sk-tabs[data-variant="retro"] .sk-tabs__trigger[aria-selected="true"] {
  text-shadow: 0 0 4px hsl(var(--sk-foreground) / 0.4);
  box-shadow: inset 0 0 6px hsl(var(--sk-foreground) / 0.05);
}

/* ASCII variant */
.sk-tabs[data-variant="ascii"] .sk-tabs__list { background: transparent; border: none; gap: 0; padding: 0; }
.sk-tabs[data-variant="ascii"] .sk-tabs__trigger { border: none; border-bottom: 1px dashed hsl(var(--sk-border-color)); border-radius: 0; }
.sk-tabs[data-variant="ascii"] .sk-tabs__trigger[aria-selected="true"] { border-bottom: 2px solid hsl(var(--sk-foreground)); background: transparent; }

/* Loading */
.sk-tabs[data-loading] .sk-tabs__content { position: relative; opacity: 0.5; pointer-events: none; }
.sk-tabs[data-loading] .sk-tabs__content::after {
  content: ""; position: absolute; inset: 0;
  background-image: var(--sk-dither-pattern); background-repeat: repeat;
  opacity: 0.06; animation: sk-pulse-dither 2s ease-in-out infinite; pointer-events: none;
}

/* Skeleton */
.sk-tabs[data-skeleton] .sk-tabs__trigger { color: transparent; background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-accent)) 50%, hsl(var(--sk-muted)) 75%); background-size: 200% 100%; animation: sk-card-shimmer 1.8s ease-in-out infinite; }

@media print {
  .sk-tabs__list { display: none; }
  .sk-tabs__content { border: none; padding: 0; }
  .sk-tabs__content[hidden] { display: none; }
  .sk-tabs[data-skeleton] { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .sk-tabs__trigger { transition: none; transform: none; }
  .sk-tabs[data-skeleton] .sk-tabs__trigger { animation: none; background: hsl(var(--sk-muted)); }
  .sk-tabs[data-loading] .sk-tabs__content::after { animation: none; }
}
